use serde_json::{json,Value};use std::{collections::HashMap,sync::{Arc,Mutex,mpsc},sync::atomic::{AtomicU64,Ordering},time::Duration};use tauri::{Emitter,State};use tauri_plugin_shell::{process::{CommandChild,CommandEvent},ShellExt};
struct Backend{child:Mutex<Option<CommandChild>>,pending:Mutex<HashMap<u64,mpsc::Sender<Result<Value,String>>>>,seq:AtomicU64}type Shared=Arc<Backend>;
fn request(s:&Shared,cmd:&str,data:Value,timeout:u64)->Result<Value,String>{let id=s.seq.fetch_add(1,Ordering::Relaxed);let(tx,rx)=mpsc::channel();s.pending.lock().map_err(|_|"pending lock")?.insert(id,tx);let line=json!({"id":id,"cmd":cmd,"data":data}).to_string()+"\n";{let mut guard=s.child.lock().map_err(|_|"backend lock")?;let child=guard.as_mut().ok_or("Python backend is not running")?;child.write(line.as_bytes()).map_err(|e|e.to_string())?;}rx.recv_timeout(Duration::from_secs(timeout)).map_err(|_|format!("Backend timed out: {cmd}"))?}
macro_rules! simple{($name:ident,$cmd:literal)=>{#[tauri::command]fn $name(s:State<'_,Shared>)->Result<Value,String>{request(&s,$cmd,json!({}),30)}}}
simple!(backend_status,"status");simple!(load_preferences,"load_preferences");simple!(list_models,"list_models");simple!(memory_data,"memory_data");simple!(lock_calendar,"lock_calendar");simple!(hardware_info,"hardware_info");simple!(stop_agent,"stop_agent");
#[tauri::command]fn save_preferences(s:State<'_,Shared>,preferences:Value)->Result<Value,String>{request(&s,"save_preferences",preferences,30)}#[tauri::command]fn set_model(s:State<'_,Shared>,model:String)->Result<Value,String>{request(&s,"set_model",json!({"model":model}),30)}#[tauri::command]fn start_agent(s:State<'_,Shared>,config:Value)->Result<Value,String>{request(&s,"start_agent",config,30)}
#[cfg_attr(mobile,tauri::mobile_entry_point)]pub fn run(){let backend=Arc::new(Backend{child:Mutex::new(None),pending:Mutex::new(HashMap::new()),seq:AtomicU64::new(1)});let setup_state=backend.clone();tauri::Builder::default().plugin(tauri_plugin_shell::init()).manage(backend).setup(move|app|{let(cmd_rx,child)=app.shell().sidecar("wiseman-backend")?.spawn()?;let mut rx=cmd_rx;*setup_state.child.lock().unwrap()=Some(child);let handle=app.handle().clone();let reader=setup_state.clone();tauri::async_runtime::spawn(async move{let mut buf=String::new();while let Some(event)=rx.recv().await{match event{CommandEvent::Stdout(bytes)=>{buf.push_str(&String::from_utf8_lossy(&bytes));while let Some(pos)=buf.find('\n'){let line=buf[..pos].trim().to_owned();buf.drain(..=pos);if line.is_empty(){continue}if let Ok(v)=serde_json::from_str::<Value>(&line){match v.get("type").and_then(Value::as_str){Some("log")=>{let _=handle.emit("backend-log",v["payload"].clone());},Some("status")|Some("ready")=>{let _=handle.emit("backend-status",v["payload"].clone());},Some("response")=>{let p=&v["payload"];if let Some(id)=p.get("id").and_then(Value::as_u64){if let Some(tx)=reader.pending.lock().unwrap().remove(&id){let r=if p.get("ok").and_then(Value::as_bool).unwrap_or(false){Ok(p.get("result").cloned().unwrap_or(Value::Null))}else{Err(p.get("error").and_then(Value::as_str).unwrap_or("Backend error").to_owned())};let _=tx.send(r);}}},_=>{}}}}},CommandEvent::Stderr(bytes)=>{let _=handle.emit("backend-log",String::from_utf8_lossy(&bytes).to_string());},_=>{}}}});Ok(())}).invoke_handler(tauri::generate_handler![backend_status,load_preferences,save_preferences,list_models,set_model,memory_data,lock_calendar,hardware_info,start_agent,stop_agent]).run(tauri::generate_context!()).expect("Tauri run failed");}
